import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
  Button,
  InputGroup,
} from "react-bootstrap";

function History() {
  const TIME_LABELS = [
    "07:00","08:00","09:00","10:00","11:00","12:00",
    "13:00","14:00","15:00","16:00","17:00","18:00",
    "19:00","20:00","21:00","22:00"
  ];

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" }
  ];
  
  const currentYearCE = new Date().getFullYear();
  const yearsBE = [currentYearCE + 542, currentYearCE + 543, currentYearCE + 544];
  const timeOptions = [];
  for (let h = 7; h <= 22; h++) {
    timeOptions.push(`${h.toString().padStart(2, '0')}:00`);
  }

  const CAMERA_INDEX = {
    CAM01: 0, // วิศวะ (ฟ้า)
    CAM02: 1, // วิทยาศาสตร์ (ชมพู)
    CAM03: 2, // ศิลปศาสตร์ (ส้ม)
    CAM04: 3  // PKY (ม่วง)
  };

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, '0'));
  const [selectedYearBE, setSelectedYearBE] = useState((currentYearCE + 543).toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [data, setData] = useState({
    labels: TIME_LABELS,
    series: [[], [], [], []]
  });
  const [loading, setLoading] = useState(false);

  const daysCount = new Date(parseInt(selectedYearBE) - 543, parseInt(selectedMonth), 0).getDate();
  const daysArray = Array.from({ length: daysCount }, (_, i) => (i + 1).toString());

  useEffect(() => {
    if (parseInt(selectedDay) > daysCount) setSelectedDay(daysCount.toString());
  }, [selectedMonth, selectedYearBE, daysCount, selectedDay]);

  const handleSearch = async () => {
    setLoading(true);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, '0')}`;
    console.log("Fetching Date (CE):", formattedDate);
    try {
      const res = await fetch(`http://26.21.101.45:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);
      const result = await res.json();

      if (result.labels && result.labels.length > 0) {
        const rawSeries = Array.isArray(result.series[0])
          ? result.series[0]
          : result.series;

        const cleanSeries = rawSeries.map(v =>
          v === null || isNaN(v) ? 0 : Number(v)
        );

        const series4 = [[], [], [], []];
        const idx = CAMERA_INDEX[cameraId];

        // ใส่ข้อมูลเฉพาะเส้นที่เลือก
        series4[idx] = cleanSeries;

        setData({
          labels: TIME_LABELS,
          series: series4
        });
      } else {
        alert("ไม่พบข้อมูลในช่วงเวลาที่เลือก");
        setData({ labels: [], series: [] });
      }
    } catch (err) {
      console.error("Fetch Error:", err);
      alert("ไม่สามารถเชื่อมต่อกับ Server ได้");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card className="card-plain">
            <Card.Header>
              <Card.Title as="h4" className="font-weight-bold">
                <i className="nc-icon nc-zoom-split mr-2"></i> ค้นหาประวัติ
              </Card.Title>
            </Card.Header>
            <Card.Body>
              <Row className="align-items-center bg-white p-4 rounded shadow-sm mx-0">
                <Col lg="3" md="6" className="mb-3 mb-lg-0">
                  <Form.Group className="mb-0">
                    <label className="small font-weight-bold">สถานี</label>
                    <InputGroup>
                      <InputGroup.Text className="bg-light border-right-0">
                        <i className="nc-icon nc-bus-front-12"></i>
                      </InputGroup.Text>
                      <Form.Control as="select" className="border-left-0" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                        <option value="CAM01">วิศวะ (CAM01)</option>
                        <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                        <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                        <option value="CAM04">หอพัก PKY (CAM04)</option>
                      </Form.Control>
                    </InputGroup>
                  </Form.Group>
                </Col>
                <Col lg="4" md="6">
                  <label className="small font-weight-bold">วันที่ (พ.ศ.)</label>
                  <div className="d-flex border rounded bg-light p-1">
                    <Form.Control as="select" className="border-0 bg-transparent" value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>
                      {daysArray.map(d => <option key={d} value={d}>{d}</option>)}
                    </Form.Control>
                    <Form.Control as="select" className="border-0 bg-transparent" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>
                      {monthsThai.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                    </Form.Control>
                    <Form.Control as="select" className="border-0 bg-transparent" value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map(y => <option key={y} value={y}>{y}</option>)}
                    </Form.Control>
                  </div>
                </Col>
                <Col lg="3" md="8">
                  <label className="small font-weight-bold">ช่วงเวลา</label>
                  <div className="d-flex align-items-center border rounded bg-light p-1">
                    <Form.Control as="select" className="border-0 bg-transparent" value={startTime} onChange={(e) => setStartTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Control>
                    <span className="mx-2">-</span>
                    <Form.Control as="select" className="border-0 bg-transparent" value={endTime} onChange={(e) => setEndTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Control>
                  </div>
                </Col>
                <Col lg="2" md="4">
                  <Button className="btn-fill w-100 mt-lg-4" variant="info" onClick={handleSearch} disabled={loading}>
                    {loading ? "กำลังโหลด..." : "ค้นหา"}
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {data.labels.length > 0 && (
        <Row className="mt-4">
          <Col md="12">
            <Card className="shadow">
              <Card.Header>
                <Card.Title as="h4" className="text-primary font-weight-bold">กราฟแสดงผล: {cameraId}</Card.Title>
                <p className="card-category">
                    วันที่ {selectedDay} {monthsThai.find(m => m.val === selectedMonth)?.name || ""} {selectedYearBE}
                </p>
              </Card.Header>
              {/* <Card.Body>
                <div className="ct-chart" style={{ height: "300px" }}>
                  <ChartistGraph
                    data={data}
                    type="Line"
                    options={{
                      low: 0,
                      height: "245px",          // ✅ เหมือน Dashboard
                      axisX: { showGrid: false },
                      lineSmooth: false,
                      showPoint: true,
                      fullWidth: true,
                      chartPadding: { right: 50 },
                    }}
                  />
                </div>
              </Card.Body> */}
              <Card.Body>
                <div className="ct-chart">
                  <div style={{width: chartData.labels.length * 70, height: "400px"}}>
                    <ChartistGraph
                      data={barChartData}
                      type="Bar"
                      options={barChartOptions}
                      listener={{draw: drawBarLabels}}
                    />
                  </div>
                </div>
              </Card.Body>
              <Card.Footer className="text-center text-muted">
                ปัดซ้าย–ขวาเพื่อดูแต่ละช่วงเวลา
              </Card.Footer>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
